def extract_code(reply: str) -> str:
    """Return the Python inside the first ```py ... ``` block, stripped."""
    fence = "```py"
    start = reply.index(fence) + len(fence)
    end = reply.index("```", start)
    return reply[start:end].strip()

reply = "Sure!\n```py\nresult = 6 * 7\n```\nDone"
print(extract_code(reply))
